// === Tab: mySketch ===
function setup() {
	createCanvas(700, 700);
	colorMode(HSB,100);
	background(0);
	angleMode(DEGREES);
	strokeWeight(7);
}
let a=0;
let x=350;
let y=350;
let xx=0;
let yy=0;
let aa=0;
let t=0;
function draw() {
	stroke(t%100,100,100);
	xx=x;
	yy=y;
	aa=a;
	line(x,y,x+cos(a)*20,y+sin(a)*20);
	x+=cos(a)*20;
	y+=sin(a)*20;
	if (random(1)<0.5) {a+=60} else {a-=60;}
	if (x>700||x<0||y>700||y<0) {x=xx;y=yy;a=aa;a+=120}
	t++;
}
